import { watchDeadline } from '../time.js';
import { $, esc, link, button, badge, empty, skeleton, field, area, select, modal as baseModal, formatDate, dateFields, resolveDate, replaceContent, allPages } from '../ui/core.js';
import { header, paginated, toast } from '../ui/session.js';

function modal(options){const dialog=baseModal(options);dialog.classList.add('care-health-dialog');const stop=options.ctx?.add?.(()=>{if(dialog.isConnected)dialog.close();});dialog.addEventListener('close',()=>stop?.(),{once:true});return dialog;}
function branchContext(parent){let alive=true;const disposers=new Set();const add=fn=>{let live=true;const stop=()=>{if(!live)return;live=false;disposers.delete(stop);fn();};disposers.add(stop);return stop;};const ctx={...parent,get alive(){return alive&&parent.alive;},get connected(){return parent.connected;},add,watch(name,args,receive,onError){return add(parent.watch(name,args,value=>{if(alive)receive(value);},error=>{if(alive)onError?.(error);}));}};const dispose=()=>{alive=false;for(const stop of [...disposers])stop();};parent.add(dispose);return {ctx,dispose};}
const tabs=[['profile','Overview'],['medicines','Medicines'],['providers','Care team'],['notes','Notes'],['followups','Waiting for'],['availability','Availability']];
const stamp=(ctx,value)=>value?formatDate(value,ctx.household.timezone):'Not yet reviewed';
const sourceFields=(s={})=>`<input type="hidden" name="sourceVersion" value="${esc(s.versionId||'')}"><input type="hidden" name="sourceOriginalDocument" value="${esc(s.documentId||'')}">`+field('sourceLabel','Where this came from',s.label||'','text','maxlength="300" placeholder="e.g. Reviewed with the pharmacist"')+field('sourceDocument','Record ID — if applicable',s.documentId||'','text','placeholder="Leave empty for a personal note"')+field('sourcePage','Page — if applicable',s.page||'','number','min="1" max="1000"');
const sourceValue=d=>({label:d.get('sourceLabel')||'Entered by a family member',...(d.get('sourceDocument')?{documentId:d.get('sourceDocument'),...(d.get('sourceVersion')&&d.get('sourceOriginalDocument')===d.get('sourceDocument')?{versionId:d.get('sourceVersion')}:{})}:{}),...(d.get('sourcePage')?{page:Number(d.get('sourcePage'))}:{})});
const sourceText=(ctx,s)=>`<p class="care-source">${s?.documentId&&!ctx.externalPack?link(ctx.path('/records/'+s.documentId+(s.versionId?'?version='+s.versionId+(s.page?'&page='+s.page:''):'')),s.label||'Source record'):esc(s?.label||'Entered by a family member')}${s?.page?' · Page '+esc(s.page):''}</p>`;
const members=ctx=>ctx.members.map(m=>[m.membership.userId,m.displayName]);
const failView=(ctx,el)=>error=>{el.innerHTML=empty('This information is unavailable.','Your access may have changed. Refresh the page to try again.',link(ctx.path('/today'),'Back to Today','ui-button secondary'));ctx.error(error);};
function removeDialog(ctx,title,fn){modal({ctx,title,content:'<p>This removes the saved item. Check that the information is no longer needed.</p>',submit:'Remove',destructive:true,onSubmit:async()=>{await fn();toast('Removed.');}});}
function bindRow(root,rows,handlers){root.onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const row=rows.find(r=>r._id===b.closest('[data-key]')?.dataset.key);handlers[b.dataset.action]?.(row,b);};}
function fact(label,value){return `<div class="care-fact"><dt>${esc(label)}</dt><dd class="detail-prose">${esc(value||'Not provided')}</dd></div>`;}
function sourcePicker(ctx,dialog){const fieldEl=dialog.querySelector('[name="sourceDocument"]');if(!fieldEl)return;const wrap=fieldEl.closest('.ui-field');wrap.querySelector('span').textContent='Source record — if applicable';const list=document.createElement('select');list.name='sourceDocument';list.innerHTML='<option value="">No linked record</option>';const selected=fieldEl.value;const pending=document.createElement('input');pending.type='hidden';pending.name='sourceDocument';pending.value=selected;fieldEl.replaceWith(pending,list);list.disabled=true;let stopSource;const watchSource=id=>{stopSource?.();if(!id)return;stopSource=ctx.watch('records:detail',{recordId:id},data=>{if(!data&&dialog.isConnected){dialog.close();toast('Access to the source record has changed.');}},()=>{if(dialog.isConnected){dialog.close();toast('The source record is no longer accessible.');}});};watchSource(selected);list.addEventListener('change',()=>watchSource(list.value));dialog.addEventListener('close',()=>stopSource?.(),{once:true});allPages(ctx,'records:list',{householdId:ctx.id},501).then(rows=>{if(!dialog.isConnected)return;list.innerHTML='<option value="">No linked record</option>'+rows.map(r=>`<option value="${esc(r._id)}" ${r._id===selected?'selected':''}>${esc(r.title)}</option>`).join('');if(selected&&!rows.some(r=>r._id===selected))list.insertAdjacentHTML('beforeend',`<option value="${esc(selected)}" selected>Previously linked record</option>`);pending.remove();list.disabled=false;}).catch(()=>{pending.remove();list.disabled=false;list.innerHTML=`<option value="${esc(selected)}">${selected?'Keep existing source':'No linked record — records unavailable'}</option>`;});}
function profileForm(ctx,p,canManage){const dialog=modal({ctx,title:p?'Edit care essentials':'Set up care essentials',content:`<p class="ui-hint">Record what matters to the person receiving care. Medical information is shared only with the people selected below.</p>${field('preferredName','Preferred name',p?.preferredName||'','text','required maxlength="160"')}${field('dateOfBirth','Date of birth',p?.dateOfBirth||'','date')}${select('allergiesState','Allergy information',[['unknown','Unknown / not yet confirmed'],['not_provided','Not provided'],['none','Explicitly confirmed none'],['provided','Details provided']],p?.allergiesState||'unknown')}${area('allergies','Allergy details',p?.allergies||'','maxlength="4000"')}${field('pharmacy','Preferred pharmacy',p?.pharmacy||'','text','maxlength="1000"')}${field('insuranceReference','Insurance reference',p?.insuranceReference||'','text','maxlength="2000"')}${area('conditions','Relevant history / conditions',p?.conditions||'','maxlength="4000"')}${area('preferences','Routines and personal preferences',p?.preferences||'','maxlength="4000"')}${area('communication','Communication and accessibility',p?.communication||'','maxlength="2000"')}${area('emergencyInstructions','Existing emergency instructions',p?.emergencyInstructions||'','maxlength="2000" placeholder="Copy instructions already provided by the care team."')}${area('authorityStatement','Your permission to coordinate care',p?.authorityStatement||'','required maxlength="2000" placeholder="Explain the person’s consent or your role as their authorized representative."')}<fieldset class="care-access"><legend>People who can see care essentials</legend><p class="ui-hint">This also gives access to medicines, care notes and visit preparation. Records have separate sharing controls. Being a household member does not automatically grant medical access.</p>${ctx.members.filter(m=>m.membership.accessPreset!=='limited_helper'&&m.membership.userId!==(p?.createdBy||ctx.viewer.id)).map(m=>`<label class="ui-check"><input type="checkbox" name="readers" value="${esc(m.membership.userId)}" ${p?.authorizedUserIds.includes(m.membership.userId)?'checked':''} ${!canManage?'disabled':''}><span>${esc(m.displayName)}</span></label>`).join('')||'<p class="ui-hint">You can add people after inviting them to the household.</p>'}</fieldset>`,onSubmit:async d=>{await ctx.mutate('care:saveProfile',{householdId:ctx.id,expectedVersion:p?.version||0,...Object.fromEntries(['preferredName','dateOfBirth','allergiesState','allergies','pharmacy','insuranceReference','conditions','preferences','communication','emergencyInstructions','authorityStatement'].map(k=>[k,d.get(k)])),authorizedUserIds:canManage?d.getAll('readers'):p.authorizedUserIds});toast('Care essentials saved.');}});const allergy=dialog.querySelector('[name="allergies"]'),state=dialog.querySelector('[name="allergiesState"]');const sync=()=>{allergy.disabled=state.value!=='provided';if(allergy.disabled)allergy.value='';};state.onchange=sync;dialog.addEventListener('handoff:form-idle',sync);sync();const original=dialog.querySelector('form').onsubmit;dialog.querySelector('form').onsubmit=e=>{if(allergy.disabled){allergy.disabled=false;const result=original(e);allergy.disabled=true;return result;}return original(e);};}
function profileView(ctx,root,data){const p=data.profile;if(!p){root.innerHTML=empty('A shared picture of the person you care for.','Start with their name, preferences and the people trusted with their medical information.',button('Set up care essentials','setup','primary'));root.querySelector('[data-action="setup"]').onclick=()=>profileForm(ctx,null,true);return;}replaceContent(root,`<div class="care-overview"><article><div class="care-profile-title"><span class="care-initial">${esc(p.preferredName.slice(0,1).toUpperCase())}</span><div><p class="care-eyebrow">Care essentials</p><h2>${esc(p.preferredName)}</h2><p class="ui-hint">Reviewed by ${esc(ctx.name(p.reviewedBy))} · ${esc(stamp(ctx,p.reviewedAt))}</p></div>${button('Edit essentials','edit')}</div><dl class="care-facts">${fact('Date of birth',p.dateOfBirth)}${fact('Allergies',p.allergiesState==='none'?'Explicitly confirmed none':p.allergiesState==='provided'?p.allergies:p.allergiesState==='not_provided'?'Not provided':'Unknown — not yet confirmed')}${fact('Preferred pharmacy',p.pharmacy)}${fact('Insurance reference',p.insuranceReference)}${fact('Relevant history',p.conditions)}${fact('Routines & preferences',p.preferences)}${fact('Communication & access',p.communication)}${fact('Emergency instructions',p.emergencyInstructions)}</dl></article><aside class="care-aside"><h3>Keep the next step close</h3><p>Bring the relevant records, questions and medicine reference into the next visit.</p>${link(ctx.path('/visits'),'Prepare for a visit →')}${link(ctx.path('/records'),'Find a care record →')}${link(ctx.path('/care?tab=followups'),'See what you’re waiting for →')}<section><h3>Shared thoughtfully</h3><p>${esc(p.authorizedUserIds.length)} ${p.authorizedUserIds.length===1?'other person has':'other people have'} access, plus the profile creator.</p><p class="ui-hint">Your recorded authority: ${esc(p.authorityStatement)}</p></section></aside></div>`);root.querySelector('[data-action="edit"]').onclick=()=>profileForm(ctx,p,data.canManageAccess);}
export function medicineForm(ctx,m){const requestId=crypto.randomUUID();const dialog=modal({ctx,title:m?._id?'Review medicine reference':'Add medicine reference',content:`<p class="ui-hint">Copy the name and directions exactly from the source. This is a reference list, not a dosing or administration tracker.</p>${field('name','Medicine name',m?.name||'','text','required maxlength="160"')}${field('strength','Strength as written',m?.strength||'','text','maxlength="200"')}${field('route','Route as written',m?.route||'','text','maxlength="160"')}${area('instructions','Directions as written',m?.instructions||'','maxlength="3000"')}${field('prescriber','Prescriber',m?.prescriber||'','text','maxlength="200"')}${field('purpose','Purpose — if provided',m?.purpose||'','text','maxlength="1000"')}${select('status','List status',[['current','Current reference'],['uncertain','Uncertain — needs clarification'],['discontinued','Discontinued'],['archived','Archived']],m?.status||'current')}${area('reviewNote','Uncertainties or review notes',m?.reviewNote||'','maxlength="2000" placeholder="Keep conflicting instructions visible; check with the prescriber."')}${sourceFields(m?.source)}`,onSubmit:async d=>{await ctx.mutate('care:saveMedicine',{householdId:ctx.id,...(m?._id?{medicineId:m._id,expectedVersion:m.version}:{}),name:d.get('name'),strength:d.get('strength'),route:d.get('route'),instructions:d.get('instructions'),prescriber:d.get('prescriber'),purpose:d.get('purpose'),status:d.get('status'),reviewNote:d.get('reviewNote'),source:sourceValue(d),requestId});toast('Medicine reference saved.');}});sourcePicker(ctx,dialog);}
function medicineHistory(ctx,m){const dialog=modal({ctx,title:m.name+' — review history',content:'<div data-history></div>',submit:null});const stop=paginated(ctx,dialog.querySelector('[data-history]'),'care:medicineHistory',{medicineId:m._id},(el,rows)=>replaceContent(el,rows.map(r=>`<article class="care-history-item"><strong>Version ${esc(r.version)}</strong><p class="ui-hint">${esc(ctx.name(r.reviewedBy))} · ${esc(stamp(ctx,r.reviewedAt))}</p><p class="detail-prose">${esc(r.instructions||'Directions not provided')}</p>${r.reviewNote?`<p class="detail-prose">${esc(r.reviewNote)}</p>`:''}${sourceText(ctx,r.source)}</article>`).join('')||empty('No review history.','Saved reviews will appear here.')));dialog.addEventListener('close',stop,{once:true});}
function medicinesView(ctx,root){root.innerHTML=`<div class="care-section-intro"><div><h2>A reference, reviewed together.</h2><p>Keep the source and any uncertainty beside the medicine. A family review is not clinical verification.</p></div>${button('Add medicine','add','primary')}</div><nav class="ui-segments" aria-label="Medicine list"><button data-list="current" aria-pressed="true">Current</button><button data-list="uncertain" aria-pressed="false">Uncertain</button><button data-list="discontinued" aria-pressed="false">Discontinued</button><button data-list="archived" aria-pressed="false">Archived</button></nav><div data-medicines>${skeleton()}</div>`;root.querySelector('[data-action="add"]').onclick=()=>medicineForm(ctx);let stop;const load=status=>{stop?.();root.querySelectorAll('[data-list]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.list===status)));const el=root.querySelector('[data-medicines]');el.innerHTML=skeleton();stop=ctx.watch('care:listMedicines',{householdId:ctx.id,status},rows=>{replaceContent(el,rows.length?rows.map(m=>`<article class="care-entry" data-key="${esc(m._id)}"><div class="ui-section-heading"><h3>${esc(m.name)}</h3><div class="ui-actions">${button('History','history')}${button('Review / edit','edit')}</div></div><p class="ui-hint">${esc([m.strength,m.route].filter(Boolean).join(' · '))}</p><p class="detail-prose">${esc(m.instructions||'Directions not provided.')}</p>${m.prescriber?`<p class="ui-hint">Prescriber: ${esc(m.prescriber)}</p>`:''}${m.purpose?`<p>${esc(m.purpose)}</p>`:''}${m.reviewNote?`<div class="care-review-note"><strong>Review note</strong><p class="detail-prose">${esc(m.reviewNote)}</p></div>`:''}${sourceText(ctx,m.source)}<p class="ui-hint">Last confirmed by ${esc(ctx.name(m.reviewedBy))} · ${esc(stamp(ctx,m.reviewedAt))}</p></article>`).join(''):empty(status==='current'?'No current medicine references.':'No '+status+' medicines.','Add the current source and keep conflicting instructions visible.',status==='current'?button('Add medicine','add','secondary'):''));bindRow(el,rows,{edit:m=>medicineForm(ctx,m),history:m=>medicineHistory(ctx,m),add:()=>medicineForm(ctx)});},failView(ctx,el));};root.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>load(b.dataset.list));load('current');ctx.add(()=>stop?.());}
function providerForm(ctx,p){const requestId=crypto.randomUUID();modal({ctx,title:p?'Edit care-team contact':'Add care-team contact',content:field('name','Name',p?.name||'','text','required maxlength="160"')+field('role','Role',p?.role||'','text','maxlength="160" placeholder="Doctor, pharmacist, emergency contact…"')+field('organization','Practice or organization',p?.organization||'','text','maxlength="200"')+field('phone','Phone',p?.phone||'','tel','maxlength="100"')+field('email','Email',p?.email||'','email','maxlength="254"')+area('address','Address',p?.address||'','maxlength="1000"')+area('note','Contact instructions',p?.note||'','maxlength="2000"')+`<label class="ui-check"><input type="checkbox" name="emergencyContact" ${p?.emergencyContact?'checked':''}><span>Include as an emergency contact</span></label><p class="ui-hint">Saving an email here does not authorize sending medical information to it.</p>`,onSubmit:async d=>{await ctx.mutate('care:saveProvider',{householdId:ctx.id,...(p?{providerId:p._id,expectedVersion:p.version}:{}),...Object.fromEntries(['name','role','organization','phone','email','address','note'].map(k=>[k,d.get(k)])),emergencyContact:d.has('emergencyContact'),requestId});toast('Care-team contact saved.');}});}
function providersView(ctx,root){root.innerHTML=`<div class="care-section-intro"><div><h2>The people you turn to.</h2><p>Providers, pharmacy and trusted emergency contacts, kept with the care context.</p></div>${button('Add contact','add','primary')}</div><div data-providers>${skeleton()}</div>`;root.querySelector('[data-action="add"]').onclick=()=>providerForm(ctx);const el=root.querySelector('[data-providers]');ctx.watch('care:listProviders',{householdId:ctx.id},rows=>{replaceContent(el,rows.length?`<div class="care-provider-grid">${rows.map(p=>`<article class="care-provider" data-key="${esc(p._id)}"><p class="care-eyebrow">${esc(p.role||'Care-team contact')}</p><h3>${esc(p.name)}</h3><p>${esc(p.organization)}</p>${p.emergencyContact?badge('Emergency contact','attention'):''}<dl>${fact('Phone',p.phone)}${fact('Email',p.email)}${fact('Address',p.address)}</dl>${p.note?`<p class="detail-prose">${esc(p.note)}</p>`:''}<div class="ui-actions">${p.phone&&/^[+\d\s().-]+$/.test(p.phone)?`<a class="ui-button secondary" href="tel:${esc(p.phone.replace(/[^+\d]/g,''))}">Call</a>`:''}${button('Edit','edit')}${button('Remove','remove')}</div></article>`).join('')}</div>`:empty('Your care team, together.','Add the office you call, the pharmacy you use or a trusted emergency contact.',button('Add contact','add')));bindRow(el,rows,{add:()=>providerForm(ctx),edit:p=>providerForm(ctx,p),remove:p=>removeDialog(ctx,'Remove '+p.name+'?',()=>ctx.mutate('care:removeProvider',{providerId:p._id,expectedVersion:p.version}))});},failView(ctx,el));}
export function addCareNote(ctx,visitId,n){const requestId=crypto.randomUUID(),dialog=modal({ctx,title:n?'Edit care note':'Add a care note',content:area('body','What changed or needs attention?',n?.body||'','required maxlength="6000"')+dateFields(n?.occurredAt||Date.now(),ctx.household.timezone,'occurred')+sourceFields(n?.source)+`<p class="ui-hint">Notes are family observations, not diagnoses. ${visitId?'This note will be linked to the visit.':''}</p>`,onSubmit:async d=>{const occurredAt=await resolveDate(ctx,d.get('occurredDate'),d.get('occurredTime'),ctx.household.timezone,d.get('occurredChoice'));if(!occurredAt)throw {data:{message:'Choose when this happened.'}};await ctx.mutate(n?'care:editNote':'care:addNote',{...(n?{noteId:n._id,expectedVersion:n.version}:{householdId:ctx.id,requestId}),body:d.get('body'),occurredAt,...((visitId||n?.visitId)?{visitId:visitId||n.visitId}:{}),source:sourceValue(d)});toast('Care note saved.');}});sourcePicker(ctx,dialog);}
function notesView(ctx,root){root.innerHTML=`<div class="care-section-intro"><div><h2>A little context for the next person.</h2><p>Short observations and changes, with their author and source.</p></div>${button('Add note','add','primary')}</div><div data-notes></div>`;root.querySelector('[data-action="add"]').onclick=()=>addCareNote(ctx);paginated(ctx,root.querySelector('[data-notes]'),'care:listNotes',{householdId:ctx.id},(el,rows)=>{replaceContent(el,rows.length?rows.map(n=>`<article class="care-note" data-key="${esc(n._id)}"><div class="care-note-byline"><span class="ui-avatar small">${esc(ctx.name(n.createdBy).slice(0,1))}</span><div><strong>${esc(ctx.name(n.createdBy))}</strong><small>${esc(stamp(ctx,n.occurredAt))} · Family observation</small></div>${button('Edit','edit')}${button('Remove','remove')}</div><p class="detail-prose">${esc(n.body)}</p>${sourceText(ctx,n.source)}${n.visitId?link(ctx.path('/visits/'+n.visitId+'/prepare'),'View linked visit →'):''}</article>`).join(''):empty('No care notes yet.','Capture something useful for the next person helping.',button('Add note','add')));bindRow(el,rows,{add:()=>addCareNote(ctx),edit:n=>addCareNote(ctx,n.visitId,n),remove:n=>removeDialog(ctx,'Remove this care note?',()=>ctx.mutate('care:removeNote',{noteId:n._id,expectedVersion:n.version}))});});}
export function followUpForm(ctx,f,visitId){const requestId=crypto.randomUUID();const dialog=modal({ctx,title:f?._id?'Update what you’re waiting for':'Track something you’re waiting for',content:field('title','Waiting for',f?.title||'','text','required maxlength="200" placeholder="e.g. The office’s answer about the referral"')+area('detail','Context and contact details',f?.detail||'','maxlength="4000"')+select('ownerId','Person following up',members(ctx),f?.ownerId||ctx.viewer.id)+'<h3>Requested / first noticed</h3>'+dateFields(f?.requestedAt||Date.now(),ctx.household.timezone,'requested')+'<h3>Follow up by</h3>'+dateFields(f?.dueAt||Date.now()+86400000,ctx.household.timezone)+select('contactId','Contact to follow up with',[['','No contact selected']],'')+select('status','Status',[['waiting','Waiting for a response'],['received','Received — still needs review'],['closed','Resolved / closed']],f?.status||'waiting')+area('resolution','Response or resolution',f?.resolution||'','maxlength="4000"')+sourceFields(f?.source),onSubmit:async d=>{const requestedAt=await resolveDate(ctx,d.get('requestedDate'),d.get('requestedTime'),ctx.household.timezone,d.get('requestedChoice'));const dueAt=await resolveDate(ctx,d.get('dueDate'),d.get('dueTime'),ctx.household.timezone,d.get('dueChoice'));if(!dueAt)throw {data:{message:'Choose a follow-up date and time.'}};await ctx.mutate('care:saveFollowUp',{householdId:ctx.id,...(f?._id?{followUpId:f._id,expectedVersion:f.version}:{}),title:d.get('title'),detail:d.get('detail'),ownerId:d.get('ownerId'),dueAt,...(requestedAt?{requestedAt}:{}),...(d.get('contactId')?{contactId:d.get('contactId')}:{}),status:d.get('status'),resolution:d.get('resolution'),source:sourceValue(d),...((visitId||f?.visitId)?{visitId:visitId||f.visitId}:{}),...(f?.taskId?{taskId:f.taskId}:{}),requestId});toast('Follow-up saved.');}});sourcePicker(ctx,dialog);const contact=dialog.querySelector('[name="contactId"]');ctx.query('care:listProviders',{householdId:ctx.id}).then(rows=>{if(!dialog.isConnected)return;contact.innerHTML='<option value="">No contact selected</option>'+rows.map(p=>`<option value="${esc(p._id)}" ${p._id===f?.contactId?'selected':''}>${esc(p.name)}</option>`).join('');}).catch(()=>{});}
const followupRow=(ctx,f)=>`<article class="care-entry" data-key="${esc(f._id)}"><div class="ui-section-heading"><h3>${esc(f.title)}</h3><div class="ui-actions">${f.mailUnread?badge('New information','attention'):''}${button('Replies & records','evidence')}${button('Update','edit')}</div></div><p class="ui-hint">${esc(ctx.name(f.ownerId))} · Follow up ${esc(stamp(ctx,f.dueAt))}</p><p class="detail-prose">${esc(f.detail)}</p>${f.resolution?`<div class="care-review-note"><strong>Response / resolution</strong><p>${esc(f.resolution)}</p></div>`:''}${sourceText(ctx,f.source)}${f.visitId?link(ctx.path('/visits/'+f.visitId+'/prepare'),'Linked visit →'):''}</article>`;
function followupsView(ctx,root){const params=new URLSearchParams(location.search),status=['waiting','received','closed'].includes(params.get('status'))?params.get('status'):'waiting';root.innerHTML=`<div class="care-section-intro"><div><h2>Keep unanswered things in view.</h2><p>A result arriving is different from someone reviewing and resolving it.</p></div>${button('Add follow-up','add','primary')}</div><nav class="ui-segments" aria-label="Follow-up status">${[['waiting','Waiting'],['received','Received'],['closed','Closed']].map(([id,label])=>`<a data-route href="${esc(ctx.path('/care?tab=followups&status='+id))}" ${id===status?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div data-followups></div>`;root.querySelector('[data-action="add"]').onclick=()=>followUpForm(ctx);if(params.get('followUp')){const requested=params.get('followUp');const url=new URL(location.href);url.searchParams.delete('followUp');history.replaceState(null,'',url.pathname+url.search);queueMicrotask(()=>{if(ctx.alive)followUpEvidence(ctx,requested);});}paginated(ctx,root.querySelector('[data-followups]'),'care:listFollowUps',{householdId:ctx.id,status},(el,rows)=>{replaceContent(el,rows.length?rows.map(f=>followupRow(ctx,f)).join(''):empty(status==='waiting'?'Nothing waiting for an answer.':'No '+status+' follow-ups.','Track a result, callback, referral or question with a named person following up.',button('Add follow-up','add')));bindRow(el,rows,{evidence:f=>followUpEvidence(ctx,f._id),edit:f=>followUpForm(ctx,f),add:()=>followUpForm(ctx)});});}
function availabilityForm(ctx,a){const requestId=crypto.randomUUID();modal({ctx,title:a?'Edit your availability':'Add your availability',content:select('state','You are',[['available','Available to help'],['unavailable','Unavailable']],a?.state||'available')+'<h3>From</h3>'+dateFields(a?.startsAt||Date.now(),ctx.household.timezone,'start')+'<h3>Until</h3>'+dateFields(a?.endsAt||Date.now()+3600000,ctx.household.timezone,'end')+area('note','What the family should know',a?.note||'','maxlength="1000" placeholder="e.g. Can take calls, but cannot drive."'),onSubmit:async d=>{const startsAt=await resolveDate(ctx,d.get('startDate'),d.get('startTime'),ctx.household.timezone,d.get('startChoice')),endsAt=await resolveDate(ctx,d.get('endDate'),d.get('endTime'),ctx.household.timezone,d.get('endChoice'));if(!startsAt||!endsAt||endsAt<=startsAt)throw {data:{message:'Choose an end time after the start.'}};await ctx.mutate('care:saveAvailability',{householdId:ctx.id,...(a?{availabilityId:a._id,expectedVersion:a.version}:{}),startsAt,endsAt,state:d.get('state'),note:d.get('note'),requestId});toast('Availability saved.');}});}
export async function requestReplacement(ctx,target,version){const requestId=crypto.randomUUID();modal({ctx,title:'Ask someone to cover',content:select('requestedMemberId','Ask',[['','Anyone in the household'],...members(ctx).filter(([id])=>id!==ctx.viewer.id)],'')+area('reason','What needs covering?','','required maxlength="2000"')+'<p class="ui-hint">You remain responsible until someone accepts. A request does not silently reassign the work.</p>',submit:'Request cover',onSubmit:async d=>{await ctx.mutate('care:requestReplacement',{householdId:ctx.id,target,targetVersion:version,requestedMemberId:d.get('requestedMemberId')||null,reason:d.get('reason'),requestId});toast('Replacement requested.');}});}
function availabilityView(ctx,root){const from=Date.now(),to=from+90*86400000;root.innerHTML=`<div class="care-section-intro"><div><h2>Make room for each other.</h2><p>Availability helps the family plan. It does not change existing assignments.</p></div>${button('Add availability','add','primary')}</div><h3>Coming up</h3><p class="ui-hint">Current and upcoming availability for the next 90 days.</p><div data-availability>${skeleton()}</div><section class="care-side-section"><h3>Requests for cover</h3><p class="ui-hint">Open requests stay with the current person until a replacement accepts.</p><div data-replacements></div></section>`;root.querySelector('[data-action="add"]').onclick=()=>availabilityForm(ctx);const el=root.querySelector('[data-availability]');ctx.watch('care:availability',{householdId:ctx.id,from,to},rows=>{replaceContent(el,rows.length?rows.map(a=>`<article class="care-availability ui-list-row" data-key="${esc(a._id)}"><span class="ui-avatar small">${esc(ctx.name(a.userId).slice(0,1))}</span><div class="row-main"><strong>${esc(ctx.name(a.userId))}</strong> ${badge(a.state==='available'?'Available':'Unavailable',a.state==='available'?'success':'neutral')}<p class="ui-hint">${esc(stamp(ctx,a.startsAt))} – ${esc(stamp(ctx,a.endsAt))}</p><p>${esc(a.note)}</p></div>${a.userId===ctx.viewer.id?`<div class="ui-actions">${button('Edit','edit')}${button('Remove','remove')}</div>`:''}</article>`).join(''):empty('No availability added.','Share when you can help, or when someone else will need to cover.'));bindRow(el,rows,{edit:a=>availabilityForm(ctx,a),remove:a=>removeDialog(ctx,'Remove this availability?',()=>ctx.mutate('care:removeAvailability',{availabilityId:a._id,expectedVersion:a.version}))});},failView(ctx,el));paginated(ctx,root.querySelector('[data-replacements]'),'care:listReplacements',{householdId:ctx.id,status:'open'},(el,rows)=>{replaceContent(el,rows.length?rows.map(r=>`<article class="care-entry" data-key="${esc(r._id)}"><div class="ui-section-heading"><strong>${esc(ctx.name(r.previousOwnerId))} needs cover</strong>${badge('Waiting for acceptance','attention')}</div><p>${esc(r.reason)}</p><p class="ui-hint">Requested from ${r.requestedMemberId?esc(ctx.name(r.requestedMemberId)):'the household'}</p><div class="ui-actions">${link(ctx.path('/'+(r.target.kind==='task'?'tasks':'coverage')+'/'+r.target.id),'View responsibility','ui-button secondary')}${r.previousOwnerId===ctx.viewer.id?button('Cancel request','cancel'):(r.requestedMemberId===null||r.requestedMemberId===ctx.viewer.id)?button('Accept responsibility','accept','primary')+button('Decline','decline'):''}</div></article>`).join(''):empty('No open requests.','Ask for cover from a responsibility when your plans change.'));bindRow(el,rows,Object.fromEntries(['accept','decline','cancel'].map(operation=>[operation,r=>modal({ctx,title:operation==='accept'?'Accept this responsibility?':operation==='decline'?'Decline this request?':'Cancel this request?',content:operation==='accept'?'<p>The responsibility will move to you when this acceptance is saved.</p>':'<p>The current person stays responsible.</p>',submit:operation==='accept'?'Accept responsibility':'Confirm',onSubmit:async()=>{await ctx.mutate('care:respondReplacement',{replacementId:r._id,expectedVersion:r.version,operation});toast('Request updated.');}})])));});}
export function carePage(ctx){const tab=new URLSearchParams(location.search).get('tab')||'profile',active=tabs.some(([id])=>id===tab)?tab:'profile';header(ctx,'Care','The person, the people and the details behind the plan.',link(ctx.path('/records'),'Care records','ui-button secondary'));const root=$('#view-body');root.innerHTML=`<nav class="care-tabs" aria-label="Care information">${tabs.map(([id,label])=>`<a data-route href="${esc(ctx.path('/care?tab='+id))}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div id="care-content">${skeleton()}</div>`;const el=$('#care-content');if(active==='availability'){availabilityView(ctx,el);return;}let initialized=false,lastAccess,branch;ctx.add(()=>branch?.dispose());ctx.watch('care:getProfile',{householdId:ctx.id},data=>{if(data.access==='restricted'){branch?.dispose();branch=null;document.querySelectorAll('.care-health-dialog').forEach(d=>d.close());el.innerHTML=empty('Medical information is shared separately.','Ask the care profile creator for access. You can still see your assigned responsibilities and share availability.',link(ctx.path('/care?tab=availability'),'View availability','ui-button secondary'));initialized=false;lastAccess='restricted';return;}if(active==='profile'){profileView(ctx,el,data);return;}if(data.access==='setup'){branch?.dispose();branch=null;el.innerHTML=empty('Set up care essentials first.','Choose who can access health information before adding medicines, contacts or care notes.',button('Set up care essentials','setup','primary'));el.querySelector('[data-action="setup"]').onclick=()=>profileForm(ctx,null,true);return;}if(!initialized||lastAccess==='restricted'){initialized=true;lastAccess=data.access;branch?.dispose();branch=branchContext(ctx);({medicines:medicinesView,providers:providersView,notes:notesView,followups:followupsView})[active](branch.ctx,el);}},failView(ctx,el));}
function questionForm(ctx,visitId,q){const requestId=crypto.randomUUID(),dialog=modal({ctx,title:q?'Update visit question':'Add a question for the visit',content:area('question','Question',q?.question||'','required maxlength="2000"')+area('answer','Answer or notes from the care team',q?.answer||'','maxlength="4000"')+select('status','Status',[['open','Still to ask'],['answered','Answered']],q?.status||'open')+sourceFields(q?.source),onSubmit:async d=>{await ctx.mutate('care:saveVisitQuestion',{householdId:ctx.id,visitId,question:d.get('question'),answer:d.get('answer'),status:d.get('status'),source:sourceValue(d),...(q?{questionId:q._id,expectedVersion:q.version}:{}),requestId});toast('Question saved.');}});sourcePicker(ctx,dialog);}
export function packMarkup(ctx,pack){let s;try{s=JSON.parse(pack.snapshot);}catch{return empty('This pack could not be read.','Create a new reviewed pack from the visit.');}return `<article class="care-pack-document"><p class="care-eyebrow">Handoff · Reviewed visit pack</p><h2>${esc(s.visit?.title||'Visit')}</h2><p>${esc(s.visit?.confirmedStartsAt?formatDate(s.visit.confirmedStartsAt,s.visit.timezone):'Date not provided')}</p><p>${esc(s.visit?.confirmedAddress||'Address not provided')}</p><p class="ui-hint">Prepared ${esc(stamp(ctx,s.reviewedAt||pack.reviewedAt))} by ${esc(ctx.name(s.reviewedBy||pack.reviewedBy))}. A family reference; confirm medical information with the care team.</p>${s.visit?.provider?`<section><h3>Care provider</h3><dl class="care-facts">${fact("Name",s.visit.provider.name)}${fact("Role",s.visit.provider.role)}${fact("Practice",s.visit.provider.organization)}${fact("Address",s.visit.provider.address)}${fact("Phone",s.visit.provider.phone)}${fact("Email",s.visit.provider.email)}</dl><p class="ui-hint">Provider directory version ${esc(s.visit.provider.version)} · updated ${esc(stamp(ctx,s.visit.provider.updatedAt))}. Saved with this reviewed pack.</p></section>`:""}${s.visit?.transport?`<section><h3>Transport & arrival</h3><dl class="care-facts">${fact('Pickup address',s.visit.transport.pickupAddress)}${fact('Pickup time',s.visit.transport.pickupAt?formatDate(s.visit.transport.pickupAt,s.visit.timezone):'Not arranged')}${fact('Arrive by',s.visit.transport.arrivalAt?formatDate(s.visit.transport.arrivalAt,s.visit.timezone):'Not arranged')}${fact('Return pickup',s.visit.transport.returnAt?formatDate(s.visit.transport.returnAt,s.visit.timezone):'Not arranged')}${fact('Return destination',s.visit.transport.returnAddress)}${fact('Accessibility',s.visit.transport.accessibilityNote)}${fact('Accompanying person',s.visit.transport.accompanyingNote)}</dl></section>`:''}${s.summary?`<section><h3>For this visit</h3><p class="detail-prose">${esc(s.summary)}</p></section>`:''}${s.profile?`<section><h3>${esc(s.profile.preferredName)} — essentials</h3><dl class="care-facts">${fact('Date of birth',s.profile.dateOfBirth)}${fact('Allergies',s.profile.allergiesState==='none'?'Explicitly confirmed none':s.profile.allergiesState==='provided'?s.profile.allergies:s.profile.allergiesState==='not_provided'?'Not provided':'Unknown — not yet confirmed')}${fact('Preferred pharmacy',s.profile.pharmacy)}${fact('Insurance reference',s.profile.insuranceReference)}${fact('Relevant history',s.profile.conditions)}${fact('Communication & access',s.profile.communication)}${fact('Preferences',s.profile.preferences)}${fact('Existing emergency instructions',s.profile.emergencyInstructions)}</dl></section>`:''}${s.medicines?.length?`<section><h3>Medicine reference</h3>${s.medicines.map(m=>`<div class="care-pack-item"><strong>${esc(m.name)}</strong><p>${esc([m.strength,m.route].filter(Boolean).join(' · '))}</p><p class="detail-prose">${esc(m.instructions||'Directions not provided')}</p><p>${esc(m.reviewNote||'')}</p><small>${esc(m.prescriber?m.prescriber+' · ':'')}${esc(m.status)} · Reviewed ${esc(stamp(ctx,m.reviewedAt))}</small>${sourceText(ctx,m.source)}</div>`).join('')}</section>`:''}${s.questions?.length?`<section><h3>Questions</h3>${s.questions.map(q=>`<div class="care-pack-item"><strong>${esc(q.question)}</strong><p class="detail-prose">${esc(q.answer||'Still to ask')}</p>${sourceText(ctx,q.source)}</div>`).join('')}</section>`:''}${s.notes?.length?`<section><h3>Recent observations</h3>${s.notes.map(n=>`<div class="care-pack-item"><p class="detail-prose">${esc(n.body)}</p><small>${esc(stamp(ctx,n.occurredAt))}</small>${sourceText(ctx,n.source)}</div>`).join('')}</section>`:''}<section><h3>Selected records</h3>${s.documents?.length?s.documents.map(d=>`<div class="care-pack-item">${ctx.externalPack?esc(d.title):link(ctx.path('/records/'+d.id+(d.versionId?'?version='+d.versionId:'')),d.title)}<p class="ui-hint">${esc(d.documentDate||'Date not provided')} · Original version retained at preparation</p></div>`).join(''):'<p>No records included.</p>'}</section><p class="care-print-footer">Handoff · Private care information · This copy does not update automatically. Original documents are listed separately.</p></article>`;}
export function showVisitPack(ctx,pack){const dialog=modal({ctx,title:'Reviewed visit pack',content:`<div class="care-pack-tools">${button('Print / save PDF','print','primary')}<p class="ui-hint">Use your browser’s print dialog to print or save a PDF. Original attachments are separate.</p></div>${packMarkup(ctx,pack)}`,submit:null});dialog.classList.add('care-pack-dialog');const watch=ctx.watch('care:getVisitPack',{packId:pack._id},current=>{if(!current){dialog.close();toast('Access to this pack has changed.');return;}const target=dialog.querySelector('.care-pack-document');if(target&&current.snapshot!==pack.snapshot){target.outerHTML=packMarkup(ctx,current);pack=current;}},()=>{dialog.close();toast('This pack is no longer accessible.');});dialog.addEventListener('close',watch,{once:true});dialog.querySelector('[data-action="print"]').onclick=()=>{dialog.classList.add('care-print-active');document.body.classList.add('care-printing');window.print();};const cleanup=()=>{document.body.classList.remove('care-printing');dialog.classList.remove('care-print-active');};window.addEventListener('afterprint',cleanup);dialog.addEventListener('close',()=>{cleanup();window.removeEventListener('afterprint',cleanup);},{once:true});}
async function packForm(ctx,visitId){let records,questions,notes;try{[records,questions,notes]=await Promise.all([allPages(ctx,'records:list',{householdId:ctx.id},501),ctx.query('care:listVisitQuestions',{visitId}),allPages(ctx,'care:listNotes',{householdId:ctx.id},501)]);}catch(error){return ctx.error(error);}if(!ctx.alive)return;const requestId=crypto.randomUUID();modal({ctx,title:'Prepare a reviewed visit pack',content:area('summary','What matters for this visit','','maxlength="6000" placeholder="Recent changes, priorities and practical instructions."')+`<fieldset><legend>Include in this pack</legend><label class="ui-check"><input type="checkbox" name="includeProfile" checked><span>Care essentials and allergy reference</span></label><label class="ui-check"><input type="checkbox" name="includeMedicines" checked><span>Medicine reference</span></label><p class="ui-hint">Review the resulting pack before sharing it.</p></fieldset><fieldset><legend>Questions</legend>${questions.map(q=>`<label class="ui-check"><input type="checkbox" name="questions" value="${esc(q._id)}" checked><span>${esc(q.question)}</span></label>`).join('')||'<p class="ui-hint">No visit questions saved.</p>'}</fieldset><fieldset><legend>Recent observations</legend>${notes.map(n=>`<label class="ui-check"><input type="checkbox" name="notes" value="${esc(n._id)}"><span>${esc(n.body.slice(0,220))}<small class="care-checkbox-meta">${esc(stamp(ctx,n.occurredAt))}</small></span></label>`).join('')||'<p class="ui-hint">No care notes saved.</p>'}</fieldset><fieldset><legend>Relevant records</legend>${records.map(r=>`<label class="ui-check"><input type="checkbox" name="documents" value="${esc(r._id)}"><span>${esc(r.title)}<small class="care-checkbox-meta">${esc(r.documentDate||'Date not provided')}</small></span></label>`).join('')||'<p class="ui-hint">No accessible records yet. You can make a pack without attachments.</p>'}</fieldset><p class="ui-hint">The pack starts private to you. This is a fixed snapshot; later changes require a new reviewed version.</p>`,submit:'Create reviewed pack',onSubmit:async d=>{const id=await ctx.mutate('care:createVisitPack',{householdId:ctx.id,visitId,summary:d.get('summary'),documentIds:d.getAll('documents'),questionIds:d.getAll('questions'),noteIds:d.getAll('notes'),includeProfile:d.has('includeProfile'),includeMedicines:d.has('includeMedicines'),readerIds:[],requestId});const pack=await ctx.query('care:getVisitPack',{packId:id});toast('Reviewed pack saved.');if(pack)queueMicrotask(()=>showVisitPack(ctx,pack));}});}
function createPackLink(ctx,p){
 let requestId=crypto.randomUUID(),requestFingerprint='',requestExpiry,created;
 const dialog=modal({ctx,title:'Create a private visit-pack link',content:field('recipientEmail','Recipient’s email address','','email','required maxlength="254"')+select('duration','Link expires after',[['1','1 hour'],['24','24 hours'],['168','7 days']],'24')+'<p class="ui-hint">The recipient must sign in with this exact email address. They can read and print this fixed pack, without joining your household or opening the original records. You can revoke the link later; saved or printed copies cannot be recalled.</p><label class="ui-check"><input type="checkbox" name="reviewed" required><span>I have reviewed this pack and have permission to share the included care information with this recipient.</span></label>',submit:'Create recipient link',onSubmit:async data=>{const fingerprint=JSON.stringify([data.get('recipientEmail').trim().toLowerCase(),data.get('duration')]);if(requestFingerprint!==fingerprint){requestId=crypto.randomUUID();requestFingerprint=fingerprint;requestExpiry=Date.now()+Number(data.get('duration'))*3600000;}created=await ctx.mutate('careShares:create',{packId:p._id,recipientEmail:data.get('recipientEmail'),expiresAt:requestExpiry,requestId});}});
 dialog.addEventListener('close',()=>{if(!created||!ctx.alive)return;const url=new URL('/visit-packs/shared?shareId='+encodeURIComponent(created),location.origin).href;const result=modal({ctx,title:'Private link ready',content:field('shareLink','Copy this link to your recipient',url,'text','readonly')+'<p class="ui-hint">Only the named recipient can open it after verifying their email. Creating the link does not send an email.</p>'+button('Copy link','copy'),submit:null});result.querySelector('[data-action="copy"]').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Private pack link copied.');}catch{toast('Select the link and copy it manually.');}};},{once:true});
}
function sharePack(ctx,p){
 const dialog=modal({ctx,title:'Share this visit pack',content:`<div class="ui-actions">${button('Review pack','review')}${button('Create recipient link','recipient','primary')}</div><h3>Expiring recipient links</h3><p class="ui-hint">Each link is bound to one verified email address. Revoke a link to stop future access.</p><div data-pack-shares>${skeleton()}</div><h3>Care-circle access</h3><p class="ui-hint">These household readers must already have care-profile access and access to every source record. This setting is separate from recipient links.</p>${ctx.members.filter(m=>m.membership.accessPreset!=='limited_helper'&&m.membership.userId!==p.createdBy).map(m=>`<label class="ui-check"><input type="checkbox" name="readers" value="${esc(m.membership.userId)}" ${p.readerIds?.includes(m.membership.userId)?'checked':''}><span>${esc(m.displayName)}</span></label>`).join('')||'<p class="ui-hint">No other care-circle members yet.</p>'}`,submit:'Save care-circle access',onSubmit:async d=>{await ctx.mutate('care:setVisitPackReaders',{packId:p._id,expectedVersion:p.version,readerIds:d.getAll('readers')});toast('Pack sharing updated.');}});
 dialog.querySelector('[data-action="recipient"]').onclick=()=>createPackLink(ctx,p);
 dialog.querySelector('[data-action="review"]').onclick=async()=>{try{const pack=await ctx.query('care:getVisitPack',{packId:p._id});if(pack&&dialog.isConnected)showVisitPack(ctx,pack);}catch(error){ctx.error(error);}};
 const root=dialog.querySelector('[data-pack-shares]');let stopExpiry;
 const render=rows=>{stopExpiry?.();const now=Date.now();replaceContent(root,rows.length?rows.map(s=>`<article class="ui-list-row" data-key="${esc(s._id)}"><div class="row-main"><strong>${esc(s.recipientEmail)}</strong><div class="row-meta">${s.revokedAt?'Revoked':s.expiresAt<=now?'Expired':'Expires '+esc(stamp(ctx,s.expiresAt))}</div></div>${!s.revokedAt&&s.expiresAt>now?`<div class="ui-actions">${button('Copy link','copy')}${button('Revoke','revoke')}</div>`:''}</article>`).join(''):empty('No recipient links.','Create a link for someone who needs this reviewed pack.'));bindRow(root,rows,{copy:async s=>{try{await navigator.clipboard.writeText(new URL('/visit-packs/shared?shareId='+encodeURIComponent(s._id),location.origin).href);toast('Private pack link copied.');}catch{modal({ctx,title:'Copy private link',content:field('link','Recipient link',new URL('/visit-packs/shared?shareId='+encodeURIComponent(s._id),location.origin).href,'text','readonly'),submit:null});}},revoke:s=>modal({ctx,title:'Revoke this pack link?',content:`<p>${esc(s.recipientEmail)} will no longer be able to open this link. Saved or printed copies cannot be recalled.</p>`,submit:'Revoke link',onSubmit:async()=>{await ctx.mutate('careShares:revoke',{shareId:s._id});toast('Pack link revoked.');}})});const next=Math.min(...rows.filter(s=>!s.revokedAt&&s.expiresAt>now).map(s=>s.expiresAt));if(Number.isFinite(next))stopExpiry=watchDeadline(next,expired=>{if(expired&&dialog.isConnected)render(rows);});};
 const stop=ctx.watch('careShares:list',{packId:p._id},render,()=>{dialog.close();toast('Sharing is no longer available. Your access may have changed.');});dialog.addEventListener('close',()=>{stop();stopExpiry?.();},{once:true});
}
export function visitPreparation(ctx,id){header(ctx,'Visit preparation','Questions, records and the next steps after the appointment.',link(ctx.path('/visits/'+id),'Visit & transport','ui-button secondary'));const root=$('#view-body');root.innerHTML=skeleton();let initialized=false,visit,branch;ctx.add(()=>branch?.dispose());ctx.watch('care:getProfile',{householdId:ctx.id},access=>{if(access.access!=='allowed'){branch?.dispose();branch=null;document.querySelectorAll('.care-health-dialog').forEach(d=>d.close());root.innerHTML=empty(access.access==='setup'?'Set up care essentials first.':'Visit preparation contains private care information.',access.access==='setup'?'Choose who can access health information before preparing the visit.':'Ask the care profile creator to grant you access. Visit logistics remain available.',link(ctx.path('/care'),'Care essentials','ui-button secondary'));initialized=false;return;}if(initialized)return;initialized=true;branch=branchContext(ctx);const live=branch.ctx;root.innerHTML=`<div data-visit-summary>${skeleton()}</div><div class="care-visit-layout"><div><section class="care-visit-section"><div class="ui-section-heading"><h2>Questions for the visit</h2>${button('Add question','question','primary')}</div><p class="ui-hint">Keep the source alongside the question. Record the care team’s answer afterwards.</p><div data-questions>${skeleton()}</div></section><section class="care-visit-section"><div class="ui-section-heading"><h2>Reviewed visit packs</h2>${button('Prepare pack','pack','primary')}</div><p class="ui-hint">Select the information you want to bring. Each pack is a reviewed snapshot.</p><div data-packs>${skeleton()}</div></section><section class="care-visit-section"><div class="ui-section-heading"><h2>After the visit</h2>${button('Add visit note','note')}</div><p>Capture what you heard, attach the new paperwork and name the person following up.</p><div class="ui-actions">${button('Track a result or answer','followup')}${link(ctx.path('/records'),'Add the new record','ui-button secondary')}${link(ctx.path('/care?tab=notes'),'Care notes','ui-button secondary')}</div><div data-visit-followups></div></section></div><aside class="care-aside"><h3>Bring the right context</h3>${link(ctx.path('/care?tab=medicines'),'Review medicine reference →')}${link(ctx.path('/records'),'Find relevant paperwork →')}${link(ctx.path('/places'),'Open care locations →')}<section><h3>The ride is its own responsibility.</h3><p>Confirm who is driving and accompanying your parent. Keep pickup and return arrangements with the visit.</p>${link(ctx.path('/visits/'+id),'Review transport →')}</section><section><h3>What comes next?</h3><p>New results need a review. An unanswered question stays open until someone explicitly closes it.</p>${link(ctx.path('/care?tab=followups'),'All waiting items →')}</section></aside></div>`;
 live.watch('visits:get',{visitId:id},data=>{visit=data.visit;if(visit.householdId!==ctx.id)return ctx.unavailable();replaceContent(root.querySelector('[data-visit-summary]'),`<div class="care-visit-summary"><p class="care-eyebrow">${esc(visit.status)} visit</p><h2>${esc(visit.title)}</h2><p>${esc(formatDate(visit.confirmedStartsAt,visit.timezone))} · ${esc(visit.timezone)}</p><p class="ui-hint">${esc(visit.confirmedAddress||'Address not yet added')}${data.ride?' · Ride: '+esc(ctx.name(data.ride.ownerId)):' · No ride linked yet'}</p></div>`);},failView(ctx,root.querySelector('[data-visit-summary]')));
 const qel=root.querySelector('[data-questions]');live.watch('care:listVisitQuestions',{visitId:id},rows=>{replaceContent(qel,rows.length?rows.map(q=>`<article class="care-question" data-key="${esc(q._id)}"><div class="ui-section-heading"><strong>${esc(q.question)}</strong>${badge(q.status==='answered'?'Answered':'Still to ask',q.status==='answered'?'success':'neutral')}</div>${q.answer?`<p class="detail-prose">${esc(q.answer)}</p>`:''}${sourceText(ctx,q.source)}<div class="ui-actions">${button('Edit / answer','edit')}${button('Remove','remove')}</div></article>`).join(''):empty('What would you like to ask?','Add the questions you want answered before the visit starts.'));bindRow(qel,rows,{edit:q=>questionForm(live,id,q),remove:q=>removeDialog(ctx,'Remove this visit question?',()=>ctx.mutate('care:removeVisitQuestion',{questionId:q._id,expectedVersion:q.version}))});},failView(ctx,qel));
 const pel=root.querySelector('[data-packs]');live.watch('care:listVisitPacks',{visitId:id},rows=>{replaceContent(pel,rows.length?rows.map(p=>`<article class="care-pack-row" data-key="${esc(p._id)}"><div><strong>Visit pack · Version ${esc(p.version)}</strong><small>Reviewed ${esc(stamp(ctx,p.reviewedAt))} · ${esc(ctx.name(p.reviewedBy))}</small><small>${p.readerIds?.length?`${p.readerIds.length} care-circle readers`:'No additional care-circle readers'}</small></div><div class="ui-actions">${button('Open / print','open')}${p.createdBy===ctx.viewer.id?button('Sharing','share'):''}</div></article>`).join(''):empty('No reviewed pack yet.','Bring questions, the medicine reference and selected records together.'));bindRow(pel,rows,{open:async p=>{try{const current=await ctx.query('care:getVisitPack',{packId:p._id});if(current)showVisitPack(live,current);else toast('This pack is no longer available.');}catch(error){ctx.error(error);}},share:p=>sharePack(live,p)});},failView(ctx,pel));
 const fel=root.querySelector('[data-visit-followups]');paginated(live,fel,'care:listFollowUps',{householdId:ctx.id,status:'waiting'},(el,rows)=>{const linked=rows.filter(f=>f.visitId===id);replaceContent(el,linked.length?linked.map(f=>followupRow(ctx,f)).join(''):'');bindRow(el,linked,{evidence:f=>followUpEvidence(live,f._id),edit:f=>followUpForm(ctx,f,id)});});
 root.querySelector('[data-action="question"]').onclick=()=>questionForm(live,id);root.querySelector('[data-action="pack"]').onclick=()=>packForm(live,id);root.querySelector('[data-action="note"]').onclick=()=>addCareNote(live,id);root.querySelector('[data-action="followup"]').onclick=()=>followUpForm(live,null,id);
 },failView(ctx,root));}

export function followUpEvidence(ctx,followUpId){
 const dialog=modal({ctx,title:'Replies & records',content:skeleton(),submit:null});const root=dialog.querySelector('.ui-dialog-body');let current;
 const stop=ctx.watch('followUpMail:detail',{followUpId},data=>{if(!dialog.isConnected)return;current=data;root.innerHTML=`<div class="ui-section-heading"><h3>${esc(data.followUp.title)}</h3>${data.unread?badge('New information','attention'):badge(data.followUp.status)}</div><p class="ui-hint">Incoming information does not resolve this item. Review the reply and originals, then update the status yourself.</p>${sourceText(ctx,data.followUp.source)}<div class="ui-actions">${button('Update status / resolution','update','primary')}${data.mailAccess&&data.unread?button('Mark information reviewed','read'):''}</div><section class="detail-card"><h3>Linked conversations</h3>${data.mailAccess?`${data.threads.map(t=>`<article class="care-entry" data-thread="${esc(t._id)}">${link(ctx.path('/inbox/'+t._id+'?view=all'),t.subject||'Untitled conversation','row-title')}<p class="ui-hint">${esc(stamp(ctx,t.lastInboundAt||t.lastMessageAt))}</p><div class="ui-actions">${button('Import an attachment','import')}${button('Unlink conversation','unlink-thread')}</div></article>`).join('')||'<p>No conversation linked yet.</p>'}${button('Link a conversation','link-thread')}`:'<p>Mail access is required to view or link conversations.</p>'}</section><section class="detail-card"><h3>Relevant originals</h3>${data.records.map(r=>`<article class="care-entry" data-record="${esc(r._id)}">${link(ctx.path('/records/'+r._id),r.title,'row-title')}<div class="ui-actions">${button('Unlink record','unlink-record')}</div></article>`).join('')||'<p>No accessible records linked.</p>'}${button('Link an existing record','link-record')}<p class="ui-hint">Linking a record does not change who can read it.</p></section>`;},()=>{if(dialog.isConnected){root.innerHTML=empty('Waiting item unavailable.','Its care or source permissions may have changed.');current=null;}});
 dialog.addEventListener('close',stop,{once:true});root.onclick=async event=>{const b=event.target.closest('[data-action]');if(!b||!current)return;const action=b.dataset.action,data=current;
  if(action==='update'){dialog.close();followUpForm(ctx,data.followUp);return;}
  const thread=data.threads.find(t=>t._id===b.closest('[data-thread]')?.dataset.thread),record=data.records.find(r=>r._id===b.closest('[data-record]')?.dataset.record);
  if(action==='import'&&thread){const {emailImport}=await import('./records.js');if(ctx.alive&&dialog.isConnected)emailImport(ctx,{threadId:thread._id,followUpId});return;}
  b.disabled=true;try{
   if(action==='read')await ctx.mutate('followUpMail:markRead',{followUpId,throughRevision:data.revision});
   else if(action==='unlink-thread'&&thread)await ctx.mutate('followUpMail:linkThread',{threadId:thread._id,expectedVersion:thread.version,followUpId:null});
   else if(action==='unlink-record'&&record)await ctx.mutate('followUpMail:linkRecord',{followUpId,recordId:record._id,linked:false});
   else if(action==='link-thread'){
    const rows=(await allPages(ctx,'inbox:list',{householdId:ctx.id,filter:'all'},501)).filter(t=>!t.deleting&&!t.quarantined&&!t.followUpId);if(!ctx.alive||!dialog.isConnected)return;
    modal({ctx,title:'Link a conversation',content:rows.length?select('threadId','Conversation',[['','Choose a conversation'],...rows.map(t=>[t._id,t.subject||'Untitled conversation'])],'')+'<p>Its existing responsibility or visit match stays in place. Replies will appear as new information for each reader.</p>':empty('No unlinked conversations.','Receive a message or unlink it from its current waiting item first.'),submit:rows.length?'Link conversation':null,onSubmit:async d=>{const t=rows.find(t=>t._id===d.get('threadId'));if(!t)throw {data:{message:'Choose a conversation.'}};await ctx.mutate('followUpMail:linkThread',{threadId:t._id,expectedVersion:t.version,followUpId});}});
   }else if(action==='link-record'){
    const rows=(await allPages(ctx,'records:list',{householdId:ctx.id},501)).filter(r=>!data.records.some(d=>d._id===r._id));if(!ctx.alive||!dialog.isConnected)return;
    modal({ctx,title:'Link a care record',content:rows.length?select('recordId','Original record',[['','Choose a record'],...rows.map(r=>[r._id,r.title])],'')+'<p>The original keeps its current access settings.</p>':empty('No additional accessible records.','Upload a record or import an attachment first.'),submit:rows.length?'Link record':null,onSubmit:async d=>{if(!d.get('recordId'))throw {data:{message:'Choose a record.'}};await ctx.mutate('followUpMail:linkRecord',{followUpId,recordId:d.get('recordId'),linked:true});}});
   }
  }catch(error){ctx.error(error);}finally{if(b.isConnected)b.disabled=false;}
 };
}
